const $=s=>document.querySelector(s), main=$('#main');
const tabs={oportunidades:'Radar',fornecedores:'Fornecedores',catalogo:'Catálogo',vender:'Vender',pedidos:'Pedidos',contas:'Contas'};
let page='',filter='Todos',query='',motion=matchMedia('(prefers-reduced-motion: reduce)').matches;
const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem('nixo-concept-'+key))??fallback}catch{return fallback}};
const write=(key,value)=>{try{localStorage.setItem('nixo-concept-'+key,JSON.stringify(value));return true}catch{return false}};
let favorites=read('favorites',[]),draft=read('draft',{step:0,path:[],product:null,title:'',price:'',description:'',destination:'Mercado Livre'}),suppliers=read('suppliers',[]),prefs=read('preferences',{sound:true,autosave:true});
const products=[{id:1,name:'Sapato clássico',image:'shoe.jpg',type:'Sapatos',group:'Calçados',cost:89.90,price:159.90,score:18,stock:42},{id:2,name:'Tênis casual',image:'sneaker.jpg',type:'Tênis',group:'Calçados',cost:109.90,price:189.90,score:15,stock:28},{id:3,name:'Coleção urbana',image:'fashion.jpg',type:'Roupas',group:'Roupas',cost:79.90,price:139.90,score:12,stock:16},{id:4,name:'Fone Bluetooth TWS',image:'../assets/products/product-0-hq.webp',type:'Eletrônicos',group:'Acessórios',cost:49.90,price:99.90,score:17,stock:35},{id:5,name:'Garrafa térmica',image:'../assets/products/product-2-hq.webp',type:'Utilidades',group:'Acessórios',cost:39.90,price:79.90,score:16,stock:60},{id:6,name:'Organizador de maquiagem',image:'../assets/products/product-3-hq.webp',type:'Organizadores',group:'Acessórios',cost:29.90,price:69.90,score:14,stock:24}];
const productImage=p=>p.image.startsWith('../')?p.image:'assets/'+p.image;
const brl=v=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(v);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const arrow='<svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M5 12h14m-6-6 6 6-6 6" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg>';
const handshake=`<svg viewBox="0 0 180 110" fill="none" aria-hidden="true"><ellipse cx="90" cy="55" rx="81" ry="45" fill="#fff4c4" stroke="#193550" stroke-width="4"/><path d="M15 53l36-16 29 9 26-7 51 16-22 28-18 2-23 7-28-10-27-18-24-4z" fill="#e7be91" stroke="#193550" stroke-width="3" stroke-linejoin="round"/><path d="M48 36l24 4 19-7 31 8-16 11-18-3-16 14c-8 5-18-4-11-10l10-11M74 74l11 9m1-19l15 17m1-23l17 18" stroke="#193550" stroke-width="3" stroke-linecap="round"/><path d="M13 51l22-12 16 27-22 11M145 43l23 10-10 26-20-9" fill="#b5d7e8" stroke="#193550" stroke-width="3"/></svg>`;
const icons={pessoal:`<path d="M30 35l25-15 25 15 20-5 13 27-22 12v51H38V69L16 57l13-27z" fill="#2873ee"/><path d="M55 20q12 22 25 0" fill="none" stroke="#eef3ec" stroke-width="5"/>`,casa:`<path d="M15 63L65 18l50 45-12 13-10-9v52H37V67L27 76z" fill="#9a75d6"/><path d="M53 82h26v37H53z" fill="#f9f6ff"/>`,trabalho:`<rect x="19" y="40" width="96" height="73" rx="13" fill="#ac7f5a"/><path d="M47 40V26h39v14" fill="none" stroke="#70523e" stroke-width="9"/><path d="M19 67h96" stroke="#ddbe9c" stroke-width="5"/><rect x="59" y="63" width="17" height="20" rx="3" fill="#f7e5c1"/>`,calcados:`<path d="M20 70l18-32 20 13 8 32 44 9 8 19H18V83z" fill="#b48366"/><path d="M18 112h100" stroke="#f7f2e5" stroke-width="9"/><path d="M47 63l20 3m-16 8l19 3" stroke="#f8e9d7" stroke-width="4"/>`,roupas:`<path d="M30 35l25-15 25 15 20-5 13 27-22 12v51H38V69L16 57l13-27z" fill="#9386b4"/>`,acessorios:`<circle cx="67" cy="67" r="36" fill="none" stroke="#ac7f5a" stroke-width="16"/><circle cx="67" cy="67" r="24" fill="#f7e8c2"/><path d="M67 49v18l12 8" fill="none" stroke="#785b47" stroke-width="5"/><path d="M53 11h28v22H53zm0 90h28v22H53z" fill="#785b47"/>`};
const icon=k=>`<svg viewBox="0 0 132 140" aria-hidden="true">${icons[k]||icons.calcados}</svg>`;
const head=(over,title,desc,action='')=>`<div class="page-head reveal"><div><div class="eyebrow">${over}</div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`;
const button=(text,attrs='',cls='primary btn-ink')=>`<button class="${cls}" ${attrs}>${text}<span>${arrow}</span></button>`;
function card(p,mode='radar'){return `<article class="product reveal"><div class="product-photo"><img src="${productImage(p)}" alt="${p.name}" loading="eager" decoding="async">${mode==='radar'?`<span class="score ${p.score<18?'yellow':''}"><b>Score ${p.score}</b><span>${p.score>=18?'Boa indicação':'Em análise'}</span></span>`:`<span class="score">${p.stock} disponíveis</span>`}<button class="save-btn ${favorites.includes(p.id)?'saved':''}" data-save="${p.id}" aria-label="${favorites.includes(p.id)?'Remover':'Salvar'} ${p.name}" aria-pressed="${favorites.includes(p.id)}">${favorites.includes(p.id)?'♥':'♡'}</button></div><div class="product-info"><div><h3>${p.name}</h3><p>Custo ${brl(p.cost)}<small>· &nbsp;${p.group}</small></p></div><button class="circle-btn" data-product="${p.id}" aria-label="Preparar anúncio de ${p.name}">${arrow}</button></div></article>`}
function listing(mode){const radar=mode==='radar';const list=products.filter(p=>(filter==='Todos'||filter==='Salvos'&&favorites.includes(p.id)||filter===p.group)&&p.name.toLowerCase().includes(query.toLowerCase()));return `${head(radar?'Encontre possibilidades':'Seu fornecedor, seus produtos',radar?'Um bom começo.':'Sua próxima venda. ',radar?'Poucos sinais. Boas escolhas.':'Explore os produtos antes de preparar o anúncio.',`<span class="small-status"><i></i> Fornecedor de exemplo · Studio Brasil</span>`)}<section class="cream-panel reveal"><div class="toolbar"><div class="chips">${['Todos','Calçados','Roupas','Acessórios','Salvos'].map(t=>`<button class="chip ${filter===t?'active':''}" data-filter="${t}">${t}</button>`).join('')}</div><label class="search"><svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><circle cx="10" cy="10" r="6.5" stroke="currentColor" stroke-width="1.8"/><path d="m15 15 5 5" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg><input aria-label="Buscar produto" id="search" placeholder="Qual produto você procura?" value="${esc(query)}"></label></div><div class="product-grid" id="product-grid">${list.length?list.map(p=>card(p,mode)).join(''):'<p class="empty-results">Nenhum produto nessa seleção. Experimente outro filtro.</p>'}</div><p class="notice">${radar?'<span class="info-dot">i</span><span>Scores ilustrativos: <mark>verde</mark> destaca a melhor indicação desta amostra; <mark class="yellow">amarelo</mark> indica itens que ainda precisam de avaliação.</span>':'Catálogo demonstrativo. Fotos ilustrativas; estoque e preços não representam um fornecedor real.'}</p></section>`}
function suppliersPage(){return `<section class="supplier-heading reveal"><div><div class="eyebrow">Explore fornecedores</div><h1>Boas vendas<br>começam com<br>um bom parceiro.</h1><p>Compare fornecedores, organize contatos e encontre o catálogo certo para seu negócio.</p><div class="supplier-actions">${button('Adicionar parceiro','data-action="add-supplier"','primary')}<button class="supplier-text-link" data-page="catalogo">Explorar catálogo ${arrow}</button></div></div><img src="assets/supplier-box.webp" alt="Caixa de produtos Studio Brasil" width="295" height="346"></section><section class="featured-supplier cream-panel reveal"><div class="supplier-description"><span class="pill">★ &nbsp; Fornecedor em destaque</span><h2>Studio Brasil</h2><p>Calçados, roupas e acessórios para o dia a dia. Seu ponto de partida para explorar o catálogo.</p></div><img class="supplier-fashion" src="assets/supplier-fashion.webp" alt="Camiseta verde, tênis branco e bolsa caramelo do catálogo demonstrativo" width="381" height="265"><div class="supplier-facts"><div><span>◇</span><p><b>${products.length}</b>itens de exemplo</p></div><div><span>♢</span><p><b>Moda</b>Especialidade</p></div><div><span>▱</span><p><b>Entrega</b>a confirmar</p></div>${button('Ver catálogo','data-page="catalogo"')}</div></section><section class="supplier-directory"><div class="directory-heading"><h2>Mais fornecedores para explorar</h2><p>Descubra novos parceiros e amplie suas oportunidades.</p></div>${[
['Atacado Sul','Roupas e acessórios com preço competitivo.','250','Moda','AS','south'],
['Urban Mix','Moda urbana, calçados e acessórios.','180','Moda','URBAN<br>MIX','urban'],
['Casa Nova','Casa, decoração e utilidades.','320','Casa','⌂','house']
].map(([n,d,count,kind,logo,color])=>`<article class="supplier-list-row reveal"><div class="supplier-logo ${color}">${logo}</div><div class="supplier-list-copy"><h3>${n}</h3><p>${d}</p></div><div class="supplier-list-facts"><span>◇ &nbsp; ${count} itens</span><span>♢ &nbsp; ${kind}</span></div><button class="supplier-catalog-button" data-supplier-preview="${n}">Ver catálogo ${arrow}</button></article>`).join('')}${suppliers.map(x=>`<article class="supplier-list-row reveal"><div class="supplier-logo urban">${esc(x.name.slice(0,2).toUpperCase())}</div><div class="supplier-list-copy"><h3>${esc(x.name)}</h3><p>${esc(x.source)}</p></div><span class="pill yellow">Catálogo não importado</span><button class="supplier-catalog-button" data-supplier-preview="${esc(x.name)}">Ver detalhes ${arrow}</button></article>`).join('')}<p class="supplier-disclaimer">Fornecedores e quantidades ilustrativos. Consulte o catálogo de exemplo para testar o fluxo.</p></section>`}
const uiPaths={shield:'M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6l-8-3zm-4 9 3 3 5-6',link:'M10 13a5 5 0 0 0 7 0l3-3a5 5 0 0 0-7-7l-2 2m2 6a5 5 0 0 0-7 0l-3 3a5 5 0 0 0 7 7l2-2',check:'m5 12 4 4L19 6',store:'M3 9h18l-2-6H5L3 9zm2 0v12h14V9M9 21v-7h6v7',lock:'M6 10h12v11H6V10zm3 0V6a3 3 0 0 1 6 0v4'};
const ui=k=>`<svg class="demo-ui" viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="${uiPaths[k]||uiPaths.check}" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
function marketLogo(i){return `<span class="connection-brand brand-${i}" aria-hidden="true">${i===0?handshake:i===1?'<span class="bag">S</span>':'<span class="amazon-a">a</span>'}</span>`}
function choice(label,k,value,image){const descriptions={'Uso pessoal':'Moda, calçados e acessórios','Casa e decoração':'Explore ideias para a casa','Trabalho e rotina':'Produtos para o dia a dia','Calçados':'2 produtos de exemplo','Roupas':'1 produto de exemplo','Acessórios':'3 produtos de exemplo','Sapatos':'Elegância para todos os dias','Tênis':'Conforto com estilo','Ver todos os calçados':'Compare as opções disponíveis','Ver opções disponíveis':'Confira fotos, custos e estoque'};const unavailable=['Casa e decoração','Trabalho e rotina'].includes(value);return `<button class="choice reveal ${unavailable?'choice-unavailable':''}" data-choice="${value}"><div class="choice-visual">${image?`<img src="${image.startsWith('../')?image:'assets/'+image}" alt="" decoding="async">`:icon(k)}</div><div class="choice-label"><div><strong>${label}</strong><small>${descriptions[label]||'Explore os produtos disponíveis'}</small>${unavailable?'<em>Sem itens nesta amostra</em>':''}</div><span class="choice-arrow">${arrow}</span></div></button>`}
function wizardProgress(step){const stage=step<4?0:Math.min(step-3,3);return `<div class="wizard-top"><button class="wizard-back" data-action="back" ${step===0?'disabled':''} aria-label="Voltar à etapa anterior">${arrow}</button><div class="wizard-step-info"><strong>${step===7?'Prévia concluída':['Encontre o produto','Prepare o anúncio','Escolha a plataforma','Revise e conclua'][stage]}</strong><span>${step<3?`Descoberta · escolha ${step+1} de 3`:step===3?'Selecione um produto':`Etapa ${stage+1} de 4`}</span></div><span class="wizard-autosave">${ui('check')} Rascunho local</span></div><ol class="wizard-stages" aria-label="Etapas da simulação">${['Produto','Anúncio','Destino','Revisão'].map((label,i)=>`<li class="${i===stage?'current':i<stage?'complete':''}" ${i===stage?'aria-current="step"':''}><span>${i<stage?ui('check'):i+1}</span><b>${label}</b></li>`).join('')}</ol>`}
function wizard(){const step=draft.step,p=products.find(p=>p.id===draft.product)||products[0];let body='';
 if(step===0)body=`<div class="wizard-title"><div class="eyebrow" style="justify-content:center">01 / Comece pelo universo</div><h2>O que você quer vender?</h2><p>Escolha um universo para encontrar os produtos do fornecedor.</p></div><div class="choice-grid">${choice('Uso pessoal','pessoal','Uso pessoal')}${choice('Casa e decoração','casa','Casa e decoração')}${choice('Trabalho e rotina','trabalho','Trabalho e rotina')}</div>`;
 if(step===1)body=`<div class="wizard-title"><div class="eyebrow" style="justify-content:center">02 / Vamos aproximar</div><h2>O que combina com sua ideia?</h2><p>Grupos disponíveis no catálogo de exemplo.</p></div><div class="choice-grid">${choice('Calçados','calcados','Calçados')}${choice('Roupas','roupas','Roupas')}${choice('Acessórios','acessorios','Acessórios')}</div>`;
 if(step===2)body=`<div class="wizard-title"><div class="eyebrow" style="justify-content:center">03 / Só mais uma escolha</div><h2>${draft.path[1]==='Calçados'?'Qual estilo de calçado?':'Vamos aos produtos?'}</h2><p>${draft.path[1]==='Calçados'?'Do clássico ao casual. Escolha o seu.':'O catálogo desta amostra tem poucas opções; podemos pular o próximo filtro.'}</p></div><div class="choice-grid">${draft.path[1]==='Calçados'?choice('Sapatos','calcados','Sapatos','shoe.jpg')+choice('Tênis','calcados','Tênis','sneaker.jpg')+choice('Ver todos os calçados','calcados','Todos os calçados'):choice('Ver opções disponíveis',draft.path[1]==='Acessórios'?'acessorios':'roupas','Ver opções',draft.path[1]==='Acessórios'?'../assets/products/product-0-hq.webp':'fashion.jpg')}</div>`;
 if(step===3){let list=products.filter(p=>draft.path[2]==='Sapatos'?p.type==='Sapatos':draft.path[2]==='Tênis'?p.type==='Tênis':draft.path[1]==='Calçados'?p.group==='Calçados':draft.path[1]==='Roupas'?p.group==='Roupas':draft.path[1]==='Acessórios'?p.group==='Acessórios':false);body=`<div class="wizard-title"><h2>${list.length?'Encontramos seu caminho.':'Ainda não há itens por aqui.'}</h2><p>${list.length?'Escolha o produto que você quer preparar.':'Este catálogo de exemplo não tem itens nessa seleção.'}</p></div><div class="product-grid">${list.map(p=>card(p,'catalogo')).join('')}</div>${!list.length?`<div class="wizard-action">${button('Escolher outro caminho','data-action="restart"')}</div>`:''}`}
 if(step===4)body=`<div class="wizard-title"><div class="eyebrow" style="justify-content:center">Prepare seu anúncio</div><h2>Agora, dê o seu toque.</h2><p>Revise os dados. Seu rascunho fica salvo neste navegador.</p></div><div class="wizard-form"><div><div class="product-photo"><img src="${productImage(p)}" alt="${p.name}"></div><p class="notice">Custo de exemplo ${brl(p.cost)} · ${p.stock} unidades ilustrativas</p></div><div class="form-fields"><label>Título<input id="draft-title" maxlength="100" value="${esc(draft.title||p.name)}" required></label><label>Preço de venda (R$)<input id="draft-price" type="number" min="0.01" step="0.01" value="${esc(draft.price||p.price)}" required></label><label>Descrição<textarea id="draft-description" placeholder="Descreva apenas características confirmadas.">${esc(draft.description)}</textarea></label><small id="save-state" class="notice" role="status">Rascunho local</small></div></div><div class="wizard-action">${button('Escolher destino','data-action="next"')}</div>`;
 if(step===5)body=`<div class="wizard-title"><div class="eyebrow" style="justify-content:center">A mesma experiência. Seu destino.</div><h2>Onde vamos vender?</h2><p>Escolha uma plataforma para revisar seu anúncio.</p></div><div class="destination-grid">${['Mercado Livre','Shopee','Amazon'].map((m,i)=>`<button class="destination ${draft.destination===m?'active':''}" data-destination="${m}" aria-pressed="${draft.destination===m}">${marketLogo(i)}<b>${m}</b><small>Prévia de anúncio</small><span class="destination-check">${ui('check')}</span></button>`).join('')}</div><div class="wizard-action">${button('Revisar anúncio','data-action="next"')}</div><p class="notice" style="text-align:center">Seleção demonstrativa. As integrações oficiais não estão conectadas nesta versão.</p>`;
 if(step===6)body=`<div class="wizard-title"><div class="eyebrow" style="justify-content:center">Sua decisão final</div><h2>Confira antes de continuar.</h2><p>Um bom anúncio começa com informações corretas.</p></div><div class="review"><div class="thin-row"><b>${esc(draft.title||p.name)}</b><b>${brl(Number(draft.price||p.price))}</b></div><div class="thin-row"><span>Destino</span><b>${esc(draft.destination)}</b></div><div class="thin-row"><span>Fornecedor</span><span>Studio Brasil · exemplo</span></div><p>${esc(draft.description||'Sem descrição. Adicione informações confirmadas antes de uma publicação real.')}</p><span class="pill yellow">Prévia · conexão oficial pendente</span></div><div class="wizard-action">${button('Concluir prévia','data-action="finish"')}</div><p class="notice" style="text-align:center">Esta ação salva a prévia localmente. Nenhum anúncio é publicado.</p>`;
 if(step===7)body=`<div class="success"><div class="success-icon">✓</div><h2>Sua prévia está pronta.</h2><p>Salva neste navegador. Nenhum anúncio foi publicado.</p><div class="wizard-action">${button('Preparar outro produto','data-action="restart"')}${button('Ir para o catálogo','data-page="catalogo"','secondary btn-blue')}</div></div>`;
 return `${head('Vender, sem complicar','Uma escolha por vez.','Escolha o produto, prepare o anúncio e confira o resultado.',`<span class="small-status">${ui('lock')} Rascunho salvo neste navegador</span>`)}<section class="cream-panel wizard reveal">${wizardProgress(step)}${body}${draft.path.length&&step<4?`<div class="breadcrumbs">${draft.path.map(esc).join(' &nbsp; / &nbsp; ')}</div>`:''}</section>`}
function orders(){return `${head('Depois da escolha','Tudo no seu ritmo.','Acompanhe o que precisa de atenção, sem excesso de informação.')}<section class="cream-panel reveal"><div class="summary-strip"><div><strong>3</strong>Pedidos de exemplo</div><div><strong>2</strong>A preparar</div><div><strong>1</strong>Em trânsito</div></div>${products.slice(0,3).map((p,i)=>`<div class="thin-row"><div class="row-main"><img class="mini-photo" src="${productImage(p)}" alt=""><div><h3>${p.name}</h3><p>Pedido demonstrativo #${1001+i} · ${['Mercado Livre','Shopee','Amazon'][i]}</p></div></div><div class="order-meta"><b>${brl(p.price)}</b><span class="pill ${i<2?'yellow':''}">${i<2?'A preparar':'Em trânsito'}</span><button class="circle-btn" data-order="${p.id}" aria-label="Ver detalhes do pedido ${1001+i}">↗</button></div></div>`).join('')}<p class="notice">Pedidos ilustrativos para visualizar o fluxo. Sem sincronização com marketplaces.</p></section>`}
function accounts(){return `${head('Suas conexões','Seu mundo,<br>conectado.','Organize suas lojas e escolha onde quer vender.')}<section class="connection-overview reveal"><div class="overview-symbol">${ui('link')}</div><div><b>Suas lojas, em um só lugar</b><p>Conexões, permissões e status sempre à vista.</p></div><span class="connection-count"><strong>0</strong> conectadas</span></section><section class="cream-panel connections-panel reveal"><div class="connections-heading"><div><span class="panel-kicker">Canais de venda</span><h2>Lojas e marketplaces</h2><p>Veja como cada plataforma fará parte da sua operação.</p></div><span class="preview-tag">Demonstração</span></div><div class="connection-list">${['Mercado Livre','Shopee','Amazon'].map((m,i)=>`<article class="connection-card">${marketLogo(i)}<div class="connection-copy"><h3>${m}</h3><span class="connection-status"><i></i>Não conectado</span><p>${['Prepare anúncios e acompanhe sua loja em um só lugar.','Organize seu catálogo e a operação da sua loja.','Revise seus produtos antes de escolher onde publicar.'][i]}</p><div class="connection-tags"><span>${ui('shield')} Autorização oficial</span><span>${ui('lock')} Acesso por permissão</span></div></div><button class="connection-action" data-connect="${m}" aria-label="Ver conexão com ${m}">Ver conexão ${arrow}</button></article>`).join('')}</div><div class="connection-security">${ui('shield')}<div><b>Você controla o acesso à sua loja.</b><p>Na versão integrada, a autorização acontece na própria plataforma. Esta demonstração não solicita senhas nem conecta contas reais.</p></div></div></section><div class="future-platforms reveal"><span>+</span><div><b>Mais plataformas, mais possibilidades.</b><p>Novos canais poderão ser adicionados ao Nixo.</p></div></div><section class="cream-panel account-preferences reveal"><div class="section-top"><div><h2>Do seu jeito</h2><p>Preferências desta demonstração.</p></div></div><div class="account-row"><span>Movimento suave<small>Transições leves entre as etapas.</small></span><button class="toggle" role="switch" aria-label="Movimento suave" aria-checked="${!motion}" data-action="motion"></button></div><div class="account-row"><span>Som de confirmação<small>Um toque discreto ao concluir uma prévia.</small></span><button class="toggle" role="switch" aria-label="Som de confirmação" aria-checked="${prefs.sound}" data-pref="sound"></button></div><div class="account-row"><span>Rascunhos neste navegador<small>Suas escolhas ficam salvas neste dispositivo.</small></span><span class="pill">Ativo</span></div></section>`}
function animate(){if(!window.gsap||motion)return;gsap.fromTo('.reveal',{y:25,opacity:0},{y:0,opacity:1,duration:.65,stagger:.065,ease:'power3.out'})}
function render(){if(window.gsap)gsap.killTweensOf('*');main.innerHTML=({oportunidades:()=>listing('radar'),catalogo:()=>listing('catalogo'),fornecedores:suppliersPage,vender:wizard,pedidos:orders,contas:accounts})[page]();$('#nav').innerHTML=Object.entries(tabs).map(([key,label])=>`<button data-page="${key}" class="${page===key?'active':''}" ${page===key?'aria-current="page"':''}>${label}</button>`).join('');$('#motion-toggle').textContent=motion?'Ativar movimento ▷':'Pausar movimento Ⅱ';$('#motion-toggle').setAttribute('aria-pressed',String(motion));animate()}
function navigate(){const next=location.hash.slice(1);page=tabs[next]?next:'oportunidades';filter='Todos';query='';render();scrollTo({top:0,behavior:'instant'})}
function saveDraft(){return write('draft',draft)}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000)}
function modal(html){$('#dialog-content').innerHTML=html;$('#dialog').showModal()}
function chooseProduct(id){const p=products.find(x=>x.id===id);draft={...draft,step:4,product:id,title:p.name,price:String(p.price),description:''};saveDraft();if(page==='vender')render();else location.hash='vender'}
function sound(){if(!prefs.sound)return;try{const ac=new(window.AudioContext||window.webkitAudioContext)(),o=ac.createOscillator(),g=ac.createGain();o.connect(g);g.connect(ac.destination);o.frequency.setValueAtTime(880,ac.currentTime);g.gain.setValueAtTime(.025,ac.currentTime);g.gain.exponentialRampToValueAtTime(.001,ac.currentTime+.5);o.start();o.stop(ac.currentTime+.5);o.onended=()=>ac.close()}catch{}}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.supplierPreview){modal(`<span class="pill yellow">Fornecedor de exemplo</span><h2>${esc(b.dataset.supplierPreview)}</h2><p>Este parceiro ilustra a organização dos fornecedores. O catálogo disponível para testar a simulação é o Studio Brasil, com ${products.length} produtos.</p>${button('Explorar catálogo de exemplo','data-action="open-demo-catalog"')}`)}if(b.dataset.action==='open-demo-catalog'){$('#dialog').close();location.hash='catalogo'}if(b.dataset.page){document.querySelector('header').classList.remove('menu-open');if(location.hash==='#'+b.dataset.page)return;location.hash=b.dataset.page}if(b.dataset.filter){filter=b.dataset.filter;render()}if(b.dataset.save){const id=Number(b.dataset.save);favorites=favorites.includes(id)?favorites.filter(x=>x!==id):[...favorites,id];write('favorites',favorites);b.classList.toggle('saved',favorites.includes(id));b.textContent=favorites.includes(id)?'♥':'♡';b.setAttribute('aria-pressed',String(favorites.includes(id)));b.setAttribute('aria-label',(favorites.includes(id)?'Remover':'Salvar')+' '+products.find(p=>p.id===id).name);if(filter==='Salvos')render()}if(b.dataset.product)chooseProduct(Number(b.dataset.product));if(b.dataset.choice){const v=b.dataset.choice;if(draft.step===0&&v!=='Uso pessoal'){modal(`<h2>Esse universo ainda está vazio.</h2><p>O fornecedor de exemplo possui apenas itens de uso pessoal. No Nixo conectado, as opções serão geradas pelo catálogo real.</p>${button('Explorar uso pessoal','data-action="use-personal"')}`);return}draft.path[draft.step]=v;draft.path=draft.path.slice(0,draft.step+1);draft.step++;saveDraft();render()}if(b.dataset.destination){draft.destination=b.dataset.destination;saveDraft();render()}if(b.dataset.pref){prefs[b.dataset.pref]=!prefs[b.dataset.pref];write('preferences',prefs);render()}if(b.dataset.connect)modal(`<h2>Conectar ${b.dataset.connect}</h2><p>Esta é uma prévia visual. A conexão depende de OAuth e da integração oficial implementada no Nixo.</p><p>Esta versão não recebe senha, tokens ou acesso à sua loja.</p>${button('Entendi','data-action="close"')}`);if(b.dataset.order){const p=products.find(p=>p.id===Number(b.dataset.order));modal(`<span class="pill yellow">Pedido de exemplo</span><h2>${p.name}</h2><p>1 unidade · ${brl(p.price)}</p><div class="thin-row"><span>Pagamento</span><b>Confirmado · exemplo</b></div><div class="thin-row"><span>Envio</span><b>${p.id<3?'A preparar':'Em trânsito'}</b></div><p>Nenhuma operação real será executada por esta prévia.</p>`)}const action=b.dataset.action;if(action==='add-supplier')modal(`<h2>Um novo parceiro.</h2><p>Organize suas opções. O fornecedor ativo permanece o mesmo.</p><form id="supplier-form"><label>Nome do fornecedor<input name="name" required maxlength="80" placeholder="Ex.: Distribuidora Brasil"></label><label>Site ou origem<input name="source" required maxlength="200" placeholder="Ex.: site do fornecedor"></label><button class="primary btn-ink">Salvar parceiro ↗</button></form>`);if(action==='close')$('#dialog').close();if(action==='use-personal'){$('#dialog').close();draft.path=['Uso pessoal'];draft.step=1;saveDraft();render()}if(action==='back'){draft.step=Math.max(0,draft.step-1);saveDraft();render()}if(action==='restart'){draft={step:0,path:[],product:null,title:'',price:'',description:'',destination:'Mercado Livre'};saveDraft();render()}if(action==='next'){if(draft.step===4){if(!$('#draft-title').value.trim()||!$('#draft-price').checkValidity()||!$('#draft-price').value){toast('Preencha um título e um preço válido.');return}draft.title=$('#draft-title').value.trim();draft.price=$('#draft-price').value;draft.description=$('#draft-description').value}draft.step++;saveDraft();render()}if(action==='finish'){draft.step=7;if(saveDraft()){render();sound();toast('Prévia salva. Nenhum anúncio foi publicado.')}else{draft.step=6;toast('Não foi possível salvar neste navegador. Tente novamente.')}}if(action==='motion'||b.id==='motion-toggle'){motion=!motion;render()}if(b.classList.contains('close'))$('#dialog').close()});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;const mode=page==='oportunidades'?'radar':'catalogo',list=products.filter(p=>(filter==='Todos'||filter==='Salvos'&&favorites.includes(p.id)||filter===p.group)&&p.name.toLowerCase().includes(query.toLowerCase()));$('#product-grid').innerHTML=list.length?list.map(p=>card(p,mode)).join(''):'<p class="empty-results">Nenhum produto encontrado.</p>'}if(e.target.id.startsWith('draft-')){draft.title=$('#draft-title').value;draft.price=$('#draft-price').value;draft.description=$('#draft-description').value;$('#save-state').textContent=saveDraft()?'✓ Salvo neste navegador':'Não foi possível salvar neste navegador'}});
document.addEventListener('submit',e=>{if(e.target.id==='supplier-form'){e.preventDefault();const f=new FormData(e.target),name=String(f.get('name')).trim(),source=String(f.get('source')).trim();if(!name||!source)return;const next=[...suppliers,{name,source}];if(!write('suppliers',next)){toast('Não foi possível salvar neste navegador.');return}suppliers=next;$('#dialog').close();render();toast('Parceiro salvo neste navegador.')}});
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
window.addEventListener('hashchange',navigate);navigate();
